package in.findmypg.api;

import jakarta.persistence.criteria.*;
import jakarta.validation.Valid;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.http.*;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import java.time.*;
import java.util.*;

@RestController @RequestMapping("/api")
class MarketplaceController {
    private final ListingRepository listings; private final AccountRepository accounts; private final FavoriteRepository favorites;
    private final BookingRepository bookings; private final VisitRepository visits; private final ReviewRepository reviews; private final ReportRepository reports;
    private final ConversationRepository conversations; private final MessageRepository messages; private final NotificationRepository notifications; private final AuditRepository audit;
    MarketplaceController(ListingRepository l,AccountRepository a,FavoriteRepository f,BookingRepository b,VisitRepository v,ReviewRepository r,ReportRepository rep,ConversationRepository c,MessageRepository m,NotificationRepository n,AuditRepository auditRepo){listings=l;accounts=a;favorites=f;bookings=b;visits=v;reviews=r;reports=rep;conversations=c;messages=m;notifications=n;audit=auditRepo;}
    private Account me(Jwt jwt){return accounts.findById(Long.valueOf(jwt.getSubject())).orElseThrow(()->new org.springframework.security.access.AccessDeniedException("Account not found"));}
    private ListingView view(Listing l){List<Review> rs=reviews.findByListingIdOrderByCreatedAtDesc(l.id); double avg=rs.stream().mapToInt(r->r.rating).average().orElse(0); return new ListingView(l.id,l.slug,l.title,l.city,l.locality,l.landmark,l.description,l.monthlyRent,l.deposit,l.availableBeds,l.genderPreference,l.verified,l.demo,l.coverImage,l.amenities,l.owner.name,avg,rs.size());}
    @GetMapping("/listings") PageView<ListingView> search(@RequestParam(defaultValue="") String city,@RequestParam(defaultValue="") String locality,
        @RequestParam(defaultValue="0") int minRent,@RequestParam(defaultValue="300000") int maxRent,@RequestParam(required=false) String gender,
        @RequestParam(defaultValue="false") boolean verified,@RequestParam(required=false) List<String> amenity,
        @RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size,@RequestParam(defaultValue="rent") String sort){
        int p=Math.max(0,page), n=Math.min(40,Math.max(1,size)); String c=city.trim(), loc=locality.trim();
        Specification<Listing> spec=(root,q,cb)->{List<Predicate> ps=new ArrayList<>();ps.add(cb.isTrue(root.get("available")));ps.add(cb.greaterThanOrEqualTo(root.get("monthlyRent"),Math.max(0,minRent)));ps.add(cb.lessThanOrEqualTo(root.get("monthlyRent"),Math.max(minRent,maxRent)));
            if(!c.isBlank())ps.add(cb.or(cb.like(cb.lower(root.get("city")),"%"+c.toLowerCase(Locale.ROOT)+"%"),cb.like(cb.lower(root.get("locality")),"%"+c.toLowerCase(Locale.ROOT)+"%")));if(!loc.isBlank())ps.add(cb.like(cb.lower(root.get("locality")),"%"+loc.toLowerCase(Locale.ROOT)+"%"));
            if(gender!=null&&!gender.isBlank()&&!gender.equalsIgnoreCase("any"))ps.add(cb.or(cb.equal(cb.lower(root.get("genderPreference")),gender.toLowerCase(Locale.ROOT)),cb.equal(cb.lower(root.get("genderPreference")),"any")));
            if(verified)ps.add(cb.isTrue(root.get("verified")));if(amenity!=null)for(String a:amenity){Join<Listing,String> join=root.joinSet("amenities");ps.add(cb.equal(cb.lower(join),a.toLowerCase(Locale.ROOT)));}
            q.distinct(true);return cb.and(ps.toArray(Predicate[]::new));};
        Sort order="newest".equals(sort)?Sort.by(Sort.Direction.DESC,"createdAt"):Sort.by(Sort.Direction.ASC,"monthlyRent");
        Page<Listing> result=listings.findAll(spec,PageRequest.of(p,n,order));return new PageView<>(result.getContent().stream().map(this::view).toList(),p,n,result.getTotalElements(),result.getTotalPages());
    }
    @GetMapping("/listings/{slug}") ResponseEntity<ListingView> detail(@PathVariable String slug){return listings.findBySlug(slug).filter(l->l.available).map(l->ResponseEntity.ok(view(l))).orElseGet(()->ResponseEntity.notFound().build());}
    @PostMapping("/listings/{id}/favorite") ResponseEntity<?> favorite(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){Account a=me(jwt); Listing l=listings.findById(id).orElseThrow();favorites.findByTenantIdAndListingId(a.id,id).orElseGet(()->favorites.save(new Favorite(a,l)));return ResponseEntity.noContent().build();}
    @DeleteMapping("/listings/{id}/favorite") ResponseEntity<?> unfavorite(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){Account a=me(jwt);favorites.findByTenantIdAndListingId(a.id,id).ifPresent(favorites::delete);return ResponseEntity.noContent().build();}
    @GetMapping("/favorites") List<ListingView> favoriteList(@AuthenticationPrincipal Jwt jwt){return favorites.findByTenantIdOrderByCreatedAtDesc(me(jwt).id).stream().map(f->view(f.listing)).toList();}
    @PostMapping("/bookings") ResponseEntity<?> booking(@Valid @RequestBody BookingRequest r,@AuthenticationPrincipal Jwt jwt){Account t=me(jwt);Listing l=listings.findById(r.listingId()).orElseThrow();if(!l.available)return ResponseEntity.status(409).body(Map.of("message","This room is no longer available."));Booking b=new Booking();b.tenant=t;b.listing=l;b.moveInDate=r.moveInDate();b.monthlyRent=l.monthlyRent;b.deposit=l.deposit;Booking saved=bookings.save(b);notifications.save(new Notification(l.owner,"New booking request",t.name+" requested a stay at "+l.title,"/owner"));return ResponseEntity.status(201).body(bookingView(saved));}
    @GetMapping("/bookings") List<BookingView> myBookings(@AuthenticationPrincipal Jwt jwt){return bookings.findByTenantIdOrderByCreatedAtDesc(me(jwt).id).stream().map(this::bookingView).toList();}
    @PostMapping("/visits") ResponseEntity<?> visit(@Valid @RequestBody VisitRequest r,@AuthenticationPrincipal Jwt jwt){Visit v=new Visit();v.tenant=me(jwt);v.listing=listings.findById(r.listingId()).orElseThrow();v.requestedFor=r.requestedFor();v.note=r.note();Visit saved=visits.save(v);notifications.save(new Notification(v.listing.owner,"New visit request",v.tenant.name+" requested a visit to "+v.listing.title,"/owner"));return ResponseEntity.status(201).body(visitView(saved));}
    @GetMapping("/visits") List<VisitView> myVisits(@AuthenticationPrincipal Jwt jwt){return visits.findByTenantIdOrderByRequestedForAsc(me(jwt).id).stream().map(this::visitView).toList();}
    @GetMapping("/listings/{id}/reviews") List<ReviewView> listingReviews(@PathVariable Long id){return reviews.findByListingIdOrderByCreatedAtDesc(id).stream().map(this::reviewView).toList();}
    @PostMapping("/reviews") ResponseEntity<?> createReview(@Valid @RequestBody ReviewRequest r,@AuthenticationPrincipal Jwt jwt){Account tenant=me(jwt);Listing listing=listings.findById(r.listingId()).orElseThrow();if(!bookings.findByTenantIdOrderByCreatedAtDesc(tenant.id).stream().anyMatch(b->b.listing.id.equals(listing.id)&&b.status==BookingStatus.COMPLETED))return ResponseEntity.status(403).body(Map.of("message","Reviews are available after a completed stay."));Review review=new Review();review.tenant=tenant;review.listing=listing;review.rating=r.rating();review.body=r.body();return ResponseEntity.status(201).body(reviewView(reviews.save(review)));}
    @GetMapping("/owner/listings") List<ListingView> ownerListings(@AuthenticationPrincipal Jwt jwt){return listings.findByOwnerIdOrderByCreatedAtDesc(me(jwt).id).stream().map(this::view).toList();}
    @PostMapping("/owner/listings") ResponseEntity<?> createListing(@Valid @RequestBody ListingRequest r,@AuthenticationPrincipal Jwt jwt){Account owner=me(jwt);Listing l=new Listing();l.owner=owner;l.title=r.title().trim();l.city=r.city().trim();l.locality=r.locality().trim();l.landmark=r.landmark();l.description=r.description();l.monthlyRent=r.monthlyRent();l.deposit=r.deposit();l.availableBeds=r.availableBeds();l.genderPreference=r.genderPreference()==null?"Any":r.genderPreference();l.coverImage=r.coverImage();if(r.amenities()!=null)l.amenities.addAll(r.amenities());l.slug=slug(l.title)+"-"+UUID.randomUUID().toString().substring(0,8);return ResponseEntity.status(201).body(view(listings.save(l)));}
    @PutMapping("/owner/listings/{id}") ResponseEntity<?> updateListing(@PathVariable Long id,@Valid @RequestBody ListingRequest r,@AuthenticationPrincipal Jwt jwt){Listing l=listings.findById(id).orElseThrow();if(!l.owner.id.equals(me(jwt).id))return ResponseEntity.status(403).build();l.title=r.title().trim();l.city=r.city().trim();l.locality=r.locality().trim();l.landmark=r.landmark();l.description=r.description();l.monthlyRent=r.monthlyRent();l.deposit=r.deposit();l.availableBeds=r.availableBeds();l.genderPreference=r.genderPreference()==null?"Any":r.genderPreference();l.coverImage=r.coverImage();l.amenities.clear();if(r.amenities()!=null)l.amenities.addAll(r.amenities());return ResponseEntity.ok(view(listings.save(l)));}
    @GetMapping("/owner/bookings") List<BookingView> ownerBookings(@AuthenticationPrincipal Jwt jwt){return bookings.findByListingOwnerIdOrderByCreatedAtDesc(me(jwt).id).stream().map(this::bookingView).toList();}
    @GetMapping("/owner/visits") List<VisitView> ownerVisits(@AuthenticationPrincipal Jwt jwt){return visits.findByListingOwnerIdOrderByRequestedForAsc(me(jwt).id).stream().map(this::visitView).toList();}
    @PatchMapping("/owner/bookings/{id}") ResponseEntity<?> bookingStatus(@PathVariable Long id,@RequestParam BookingStatus status,@AuthenticationPrincipal Jwt jwt){Booking b=bookings.findById(id).orElseThrow();if(!b.listing.owner.id.equals(me(jwt).id))return ResponseEntity.status(403).build();if(status!=BookingStatus.ACCEPTED&&status!=BookingStatus.DECLINED&&status!=BookingStatus.CANCELLED&&status!=BookingStatus.COMPLETED)return ResponseEntity.badRequest().body(Map.of("message","Unsupported status change."));if(status==BookingStatus.COMPLETED&&b.status!=BookingStatus.ACCEPTED)return ResponseEntity.badRequest().body(Map.of("message","Only accepted stays can be marked complete."));b.status=status;Booking saved=bookings.save(b);notifications.save(new Notification(b.tenant,"Booking status updated",b.listing.title+" is now "+status.name().toLowerCase(Locale.ROOT),"/dashboard"));return ResponseEntity.ok(bookingView(saved));}
    @PatchMapping("/owner/visits/{id}") ResponseEntity<?> visitStatus(@PathVariable Long id,@RequestParam VisitStatus status,@AuthenticationPrincipal Jwt jwt){Visit v=visits.findById(id).orElseThrow();if(!v.listing.owner.id.equals(me(jwt).id))return ResponseEntity.status(403).build();v.status=status;return ResponseEntity.ok(visitView(visits.save(v)));}
    @PostMapping("/reports") ResponseEntity<?> report(@Valid @RequestBody ReportRequest r,@AuthenticationPrincipal Jwt jwt){ListingReport x=new ListingReport();x.reporter=me(jwt);x.listing=listings.findById(r.listingId()).orElseThrow();x.reason=r.reason().trim();x.details=r.details();return ResponseEntity.status(201).body(reportView(reports.save(x)));}
    @GetMapping("/admin/reports") List<ReportView> reportQueue(){return reports.findAllByOrderByCreatedAtDesc().stream().map(this::reportView).toList();}
    @PatchMapping("/admin/reports/{id}") ResponseEntity<?> reportStatus(@PathVariable Long id,@RequestParam String status,@AuthenticationPrincipal Jwt jwt){if(!List.of("OPEN","REVIEWING","RESOLVED","DISMISSED").contains(status))return ResponseEntity.badRequest().body(Map.of("message","Unsupported report status."));ListingReport x=reports.findById(id).orElseThrow();x.status=status;reports.save(x);audit.save(new AuditEvent(me(jwt),"REPORT_"+status,"REPORT",id,x.listing.title));return ResponseEntity.ok(reportView(x));}
    @PostMapping("/conversations") ResponseEntity<?> startConversation(@Valid @RequestBody MessageRequest r,@AuthenticationPrincipal Jwt jwt){Account sender=me(jwt);if(sender.role!=Role.TENANT)return ResponseEntity.status(403).body(Map.of("message","Only residents can initiate a listing conversation."));Listing listing=listings.findById(r.listingId()).orElseThrow();Conversation c=conversations.findByTenantIdAndListingId(sender.id,listing.id).orElseGet(()->{Conversation n=new Conversation();n.tenant=sender;n.owner=listing.owner;n.listing=listing;return conversations.save(n);});Message m=new Message();m.conversation=c;m.sender=sender;m.body=r.body().trim();Message saved=messages.save(m);notifications.save(new Notification(c.owner,"New message",sender.name+" sent you a message about "+listing.title,"/owner?tab=messages"));return ResponseEntity.status(201).body(messageView(saved));}
    @GetMapping("/conversations") List<ConversationView> conversationList(@AuthenticationPrincipal Jwt jwt){Account a=me(jwt);return conversations.findByTenantIdOrOwnerIdOrderByCreatedAtDesc(a.id,a.id).stream().map(c->{List<Message> all=messages.findByConversationIdOrderByCreatedAtAsc(c.id);Message last=all.isEmpty()?null:all.get(all.size()-1);return new ConversationView(c.id,c.listing.id,c.listing.title,c.listing.locality,a.id.equals(c.tenant.id)?c.owner.name:c.tenant.name,last==null?"":last.body,last==null?c.createdAt:last.createdAt);}).toList();}
    @GetMapping("/conversations/{id}/messages") ResponseEntity<?> conversationMessages(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){Account a=me(jwt);Conversation c=conversations.findById(id).orElseThrow();if(!a.id.equals(c.tenant.id)&&!a.id.equals(c.owner.id))return ResponseEntity.status(403).build();return ResponseEntity.ok(messages.findByConversationIdOrderByCreatedAtAsc(id).stream().map(this::messageView).toList());}
    @PostMapping("/conversations/{id}/messages") ResponseEntity<?> sendMessage(@PathVariable Long id,@Valid @RequestBody MessageRequest r,@AuthenticationPrincipal Jwt jwt){Account a=me(jwt);Conversation c=conversations.findById(id).orElseThrow();if(!a.id.equals(c.tenant.id)&&!a.id.equals(c.owner.id))return ResponseEntity.status(403).build();Message m=new Message();m.conversation=c;m.sender=a;m.body=r.body().trim();Message saved=messages.save(m);Account recipient=a.id.equals(c.tenant.id)?c.owner:c.tenant;notifications.save(new Notification(recipient,"New message",a.name+" sent you a message about "+c.listing.title,"/dashboard?tab=messages"));return ResponseEntity.status(201).body(messageView(saved));}
    @GetMapping("/notifications") List<NotificationView> notificationList(@AuthenticationPrincipal Jwt jwt){return notifications.findByRecipientIdOrderByCreatedAtDesc(me(jwt).id).stream().map(n->new NotificationView(n.id,n.title,n.body,n.href,n.read,n.createdAt)).toList();}
    @PatchMapping("/notifications/{id}/read") ResponseEntity<?> readNotification(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){Account a=me(jwt);Notification n=notifications.findById(id).orElseThrow();if(!n.recipient.id.equals(a.id))return ResponseEntity.status(403).build();n.read=true;notifications.save(n);return ResponseEntity.noContent().build();}
    @GetMapping("/admin/listings") List<ListingView> adminListings(){return listings.findAll(Sort.by(Sort.Direction.DESC,"createdAt")).stream().map(this::view).toList();}
    @GetMapping("/admin/audit") List<AuditView> auditTrail(){return audit.findTop100ByOrderByCreatedAtDesc().stream().map(e->new AuditView(e.id,e.actor.name,e.action,e.entityType,e.entityId,e.detail,e.createdAt)).toList();}
    @GetMapping("/admin/accounts") List<AccountAdminView> accountQueue(){return accounts.findAll(Sort.by(Sort.Direction.DESC,"createdAt")).stream().map(a->new AccountAdminView(a.id,a.name,a.role.name(),a.enabled,a.createdAt)).toList();}
    @PatchMapping("/admin/accounts/{id}/enabled") ResponseEntity<?> accountEnabled(@PathVariable Long id,@RequestParam boolean enabled,@AuthenticationPrincipal Jwt jwt){Account admin=me(jwt),account=accounts.findById(id).orElseThrow();if(account.role==Role.ADMIN||account.id.equals(admin.id))return ResponseEntity.status(403).body(Map.of("message","Admin accounts require a separate operator process."));account.enabled=enabled;accounts.save(account);audit.save(new AuditEvent(admin,enabled?"ACCOUNT_REENABLED":"ACCOUNT_DISABLED","ACCOUNT",id,account.role.name()));return ResponseEntity.ok(new AccountAdminView(account.id,account.name,account.role.name(),account.enabled,account.createdAt));}
    @PatchMapping("/admin/listings/{id}/verification") ResponseEntity<?> verifyListing(@PathVariable Long id,@RequestParam boolean verified,@AuthenticationPrincipal Jwt jwt){Listing l=listings.findById(id).orElseThrow();l.verified=verified;Listing saved=listings.save(l);audit.save(new AuditEvent(me(jwt),verified?"LISTING_VERIFIED":"LISTING_REVIEW_REVOKED","LISTING",id,l.title));return ResponseEntity.ok(view(saved));}
    private BookingView bookingView(Booking b){return new BookingView(b.id,b.listing.id,b.listing.title,b.listing.locality,b.moveInDate,b.monthlyRent,b.deposit,b.status.name(),b.createdAt);}
    private VisitView visitView(Visit v){return new VisitView(v.id,v.listing.title,v.listing.locality,v.requestedFor,v.status.name(),v.note);}
    private ReviewView reviewView(Review r){return new ReviewView(r.id,r.rating,r.body,"Resident",r.demo,r.createdAt);}
    private ReportView reportView(ListingReport r){return new ReportView(r.id,r.listing.id,r.listing.title,r.reason,r.details,r.status,r.createdAt,r.reporter.name);}
    private MessageView messageView(Message m){return new MessageView(m.id,m.conversation.id,m.body,m.sender.name,m.createdAt);}
    private String slug(String s){return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}
}
